function validate([bulbs, k]) {
  if (!Array.isArray(bulbs) || bulbs.length < 1 || bulbs.length > 20000) return 'bulbs needs 1 to 20000 entries.';
  const n = bulbs.length;
  const seen = new Array(n + 1).fill(false);
  for (const x of bulbs) {
    if (!Number.isInteger(x) || x < 1 || x > n) return 'Each entry of bulbs is a position from 1 to n.';
    if (seen[x]) return 'bulbs must be a permutation: no position may repeat.';
    seen[x] = true;
  }
  if (!Number.isInteger(k) || k < 0 || k > 20000) return 'k is between 0 and 20000.';
  return null;
}

