    days[bulbs[day - 1] - 1] = day;
  }

  let best = Infinity;
  let left = 0;
  let right = k + 1;
  for (let i = 1; right < n; i++) {
    const reachedRight = i === right;
    const litEarlier = days[i] < days[left] || days[i] < days[right];
    if (reachedRight) {
      best = Math.min(best, Math.max(days[left], days[right]));
    }
    if (reachedRight || litEarlier) {
      left = i;
      right = i + k + 1;
    }
  }
  return best === Infinity ? -1 : best;
}

