  const n = bulbs.length;
  const on = new Array(n + 2).fill(false);
  for (let d = 0; d < n; d++) {
    on[bulbs[d]] = true;
    // Look at every pair of positions k + 1 apart and test the gap between them.
    for (let a = 1; a + k + 1 <= n; a++) {
      const b = a + k + 1;
      if (!on[a] || !on[b]) continue;
      let allOff = true;
      for (let m = a + 1; m < b; m++) if (on[m]) allOff = false;
      if (allOff) return d + 1;
    }
  }
  return -1;
}

