function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 10);
  const bulbs = Array.from({ length: n }, (_, i) => i + 1);
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [bulbs[i], bulbs[j]] = [bulbs[j], bulbs[i]];
  }
  let k;
  if (size === 'large') k = rand() < 0.7 ? Math.floor(rand() * 12) : Math.floor(rand() * n);
  else k = Math.floor(rand() * (n + 2));
  return [bulbs, k];
}
